const uint32_t m = 0x5bd1e995;
const int r = 24;

uint32_t h = seed ^ n;

// Process 4 bytes at a time
while (n >= 4) {
    uint32_t k = data[0];
    k |= data[1] << 8;
    k |= data[2] << 16;
    k |= data[3] << 24;

    k *= m;
    k ^= k >> r;
    k *= m;

    h *= m;
    h ^= k;

    data += 4;
    n -= 4;
}

// Handle remaining bytes
switch (n) {
    case 3:
        h ^= data[2] << 16;
        FALLTHROUGH_INTENDED;
    case 2:
        h ^= data[1] << 8;
        FALLTHROUGH_INTENDED;
    case 1:
        h ^= data[0];
        h *= m;
}

h ^= h >> 13;
h *= m;
h ^= h >> 15;

return h;

